      S_EMB: begin wbase = 27525120 + (tok_r >> 4) * 1024; cbase = 496000 + tok_r; end
      S_N1: begin gbase = lyr * 2048; rn_scale = c_n1s; rn_shift = c_n1h; end
      S_N2: begin gbase = lyr * 2048 + 1024; rn_scale = c_n2s; rn_shift = c_n2h; end
      S_NF: begin gbase = 57344; rn_scale = 195656; rn_shift = 24; end
      S_Q: begin wbase = lw + 0; cbase = lcb + 0; pj_depth = 1024; pj_cols = 2048; expect_n = 2048; end
      S_K: begin wbase = lw + 131072; cbase = lcb + 2048; pj_depth = 1024; pj_cols = 1024; expect_n = 1024; end
      S_V: begin wbase = lw + 196608; cbase = lcb + 3072; pj_depth = 1024; pj_cols = 1024; expect_n = 1024; end
      S_O: begin wbase = lw + 262144; cbase = lcb + 4096; pj_depth = 2048; pj_cols = 1024; expect_n = 1024; end
      S_G: begin wbase = lw + 393216; cbase = lcb + 5120; pj_depth = 1024; pj_cols = 3072; expect_n = 3072; end
      S_U: begin wbase = lw + 589824; cbase = lcb + 8192; pj_depth = 1024; pj_cols = 3072; expect_n = 3072; end
      S_DN: begin wbase = lw + 786432; cbase = lcb + 11264; pj_depth = 3072; pj_cols = 1024; expect_n = 1024; end
      S_HD: begin wbase = 27525120 + hk * 196608; cbase = 344064 + hk * 3072; pj_cols = hcols; expect_n = hcols; end
      S_R1: begin ra_sa = c_r1a; ra_sb = c_r1b; ra_sh = c_r1h; end
      S_R2: begin ra_sa = c_r2a; ra_sb = c_r2b; ra_sh = c_r2h; end
      S_ATT: expect_n = 128;
      S_QN: begin gbase = 58368 + lyr * 256; hn_scale = c_qns; hn_shift = c_qnh; expect_n = 128; end
      S_KN: begin gbase = 58368 + lyr * 256 + 128; hn_scale = c_kns; hn_shift = c_knh; expect_n = 128; end
      S_RQ: expect_n = 1024;
      S_RK: expect_n = 512;
      S_GLU: expect_n = 3072;
      default: ;
    endcase
  end
  wire in_norm = (st == S_N1) || (st == S_N2) || (st == S_NF);
  wire in_hnorm = (st == S_QN) || (st == S_KN);
  reg [12:0] ed;
  assign w_addr = wbase + ((st == S_EMB) ? ed : pj_w_addr);
  assign c_addr = cbase + ((st == S_EMB) ? 13'd0 : pj_c_addr);
  assign g_addr = gbase + (in_hnorm ? hn_g_addr : rn_g_addr);
  // The KV head this query head reads.
  wire [18:0] kvsel = lyr * 8 + hh / 2;
  assign k_raddr = kvsel * 2048 + at_k_addr;
  assign v_raddr = kvsel * 2048 + at_v_addr;
  always @(posedge clk) begin
    rn_x_data <= xm[rn_x_addr];
    pj_a_data <= (st == S_O) ? cm[pj_a_addr] : (st == S_DN) ? mm[pj_a_addr] : nm[pj_a_addr];
    if (st == S_QN) hn_x_data <= hn_x_addr[6] ? qhi[hh * 64 + hn_x_addr[5:0]] : qlo[hh * 64 + hn_x_addr[5:0]];
    else hn_x_data <= hn_x_addr[6] ? khi[hh * 64 + hn_x_addr[5:0]] : klo[hh * 64 + hn_x_addr[5:0]];
  end
  wire run_proj = (st == S_Q) || (st == S_K) || (st == S_V) || (st == S_O) ||
                  (st == S_G) || (st == S_U) || (st == S_DN) || (st == S_HD);
  wire blk_busy = run_proj ? pj_busy : in_norm ? rn_busy : in_hnorm ? hn_busy : at_busy;
  wire pj_half = pj_index[6];
  wire [12:0] pj_hadr = ((pj_index >> 7) << 6) | (pj_index & 63);
  wire [12:0] fh = fj >> 6, fp = fj & 63;
  wire [12:0] oh = ocnt >> 6, op = ocnt & 63;
  // KV cache words: keys interleaved by position, values by dimension.
  wire [18:0] kslot = (lyr * 8 + oh) * 2048 + (pos_r >> 4) * 128;
  wire [18:0] vslot = ((lyr * 8 + (pj_index >> 7)) * 256 + pos_r) * 8 + ((pj_index & 127) >> 4);
  reg ev1;
  reg [3:0] lane_r;
  wire signed [15:0] ew = w_data[lane_r * 16 +: 16];
  reg [17:0] hbase;

  always @(posedge clk) begin
    if (!rst_n) begin
      st <= S_IDLE; ph <= 1'b0; busy <= 1'b0; done <= 1'b0; hen <= 1'b0;
      lyr <= 0; hh <= 0; hk <= 0; tok_r <= 0; pos_r <= 0; next_tok <= 0;
      best <= 0; fj <= 0; ocnt <= 0; gcnt <= 0; ed <= 0; ev1 <= 1'b0; lane_r <= 0;
      pj_start <= 1'b0; rn_start <= 1'b0; at_start <= 1'b0; at_load_valid <= 1'b0; hn_start <= 1'b0;
      at_load_data <= 0; ra_a <= 0; ra_b <= 0; ra_v <= 1'b0; ro_x1 <= 0;
      ro_x2 <= 0; ro_idx <= 0; ro_v <= 1'b0; si_x <= 0; si_v <= 1'b0;
      rq_acc <= 0; rq_v <= 1'b0; rq_scale <= 0; rq_shift <= 0;
      kw0_en <= 1'b0; kw1_en <= 1'b0; vw_en <= 1'b0; kw0_addr <= 0; kw1_addr <= 0;
      vw_addr <= 0; kw0_lane <= 0; kw1_lane <= 0; vw_lane <= 0; kw0_data <= 0;
      kw1_data <= 0; vw_data <= 0; hbase <= 0;
    end else begin
      done <= 1'b0; pj_start <= 1'b0; rn_start <= 1'b0; at_start <= 1'b0; hn_start <= 1'b0;
      at_load_valid <= 1'b0; ra_v <= 1'b0; ro_v <= 1'b0; si_v <= 1'b0;
      rq_v <= 1'b0; kw0_en <= 1'b0; kw1_en <= 1'b0; vw_en <= 1'b0;
      if (run_proj && pj_valid) begin
        ocnt <= ocnt + 1;
        case (st)
          S_Q: if (pj_half) qhi[pj_hadr] <= pj_data; else qlo[pj_hadr] <= pj_data;
          S_K: if (pj_half) khi[pj_hadr] <= pj_data; else klo[pj_hadr] <= pj_data;
          S_V: begin vw_en <= 1'b1; vw_addr <= vslot; vw_lane <= pj_index[3:0];
                 vw_data <= pj_data; end
          S_O, S_DN: am[pj_index] <= pj_data;
          S_G: gm[pj_index] <= pj_data;
          S_U: um[pj_index] <= pj_data;
          S_HD: if ((hk == 0 && ocnt == 0) || pj_data > best) begin
                  best <= pj_data; next_tok <= hbase + pj_index; end
          default: ;
        endcase
      end
      if (in_norm && rn_valid) begin nm[rn_index] <= rn_data; ocnt <= ocnt + 1; end
      if (in_hnorm && hn_valid) begin
        if (st == S_QN) begin
          if (hn_index[6]) qhi[hh * 64 + hn_index[5:0]] <= hn_data; else qlo[hh * 64 + hn_index[5:0]] <= hn_data;
        end else begin
          if (hn_index[6]) khi[hh * 64 + hn_index[5:0]] <= hn_data; else klo[hh * 64 + hn_index[5:0]] <= hn_data;
        end
        ocnt <= ocnt + 1;
      end
      if (st == S_ATT && at_valid) begin
        cm[hh * 128 + at_index] <= at_data; ocnt <= ocnt + 1; end
      if ((st == S_R1 || st == S_R2) && ra_vout) begin xm[ocnt] <= ra_y; ocnt <= ocnt + 1; end
      if (st == S_RQ && ro_vout) begin qlo[ocnt] <= ro_y1; qhi[ocnt] <= ro_y2; ocnt <= ocnt + 1; end
      if (st == S_RK && ro_vout) begin
        kw0_en <= 1'b1; kw0_addr <= kslot + op; kw0_lane <= pos_r[3:0]; kw0_data <= ro_y1;
        kw1_en <= 1'b1; kw1_addr <= kslot + op + 64; kw1_lane <= pos_r[3:0]; kw1_data <= ro_y2;
        ocnt <= ocnt + 1;
      end
      if (st == S_GLU && si_vout) begin
        rq_acc <= si_y * um[gcnt]; rq_v <= 1'b1; gcnt <= gcnt + 1; end
      if ((st == S_GLU || st == S_EMB) && rq_vout) begin
        if (st == S_GLU) mm[ocnt] <= rq_q; else xm[ocnt] <= rq_q;
        ocnt <= ocnt + 1;
      end

      case (st)
        S_IDLE: if (start) begin
          tok_r <= tok; pos_r <= pos; hen <= head_en; busy <= 1'b1; lyr <= 0;
          hh <= 0; hk <= 0; st <= S_EMB; ed <= 0; ev1 <= 1'b0; ocnt <= 0; ph <= 1'b0;
          lane_r <= tok[3:0];
        end
        // The embedding row out of the head's weight words, requantized
        // with this token's own constants.
        S_EMB: begin
          rq_scale <= c_data[17:0]; rq_shift <= c_data[24:18];
          if (ed < 1024) ed <= ed + 1;
          ev1 <= (ed < 1024);
          if (ev1) begin rq_acc <= ew; rq_v <= 1'b1; end
          if (ocnt == 1024) begin ocnt <= 0; fj <= 0; ph <= 1'b0; st <= S_N1; end
        end
        S_R1, S_R2: begin
          if (fj < 1024) begin ra_a <= xm[fj]; ra_b <= am[fj]; ra_v <= 1'b1; fj <= fj + 1; end
          if (ocnt == 1024) begin
            fj <= 0; ocnt <= 0; ph <= 1'b0;
            if (st == S_R1) st <= S_N2;
            else if (lyr + 1 < 28) begin lyr <= lyr + 1; st <= S_N1; end
            else if (hen) begin st <= S_NF; end
            else begin busy <= 1'b0; done <= 1'b1; st <= S_IDLE; end
          end
        end
        S_RQ, S_RK: begin
          if (fj < expect_n) begin
            ro_x1 <= (st == S_RQ) ? qlo[fj] : klo[fj];
            ro_x2 <= (st == S_RQ) ? qhi[fj] : khi[fj];
            ro_idx <= fp[5:0]; ro_v <= 1'b1; fj <= fj + 1;
          end
          if (ocnt == expect_n) begin fj <= 0; ocnt <= 0; ph <= 1'b0;
            st <= (st == S_RQ) ? S_RK : S_LQ; end
        end
        S_LQ: begin
          if (fj < 128) begin
            at_load_valid <= 1'b1;
            at_load_data <= fj[6] ? qhi[hh * 64 + fj[5:0]] : qlo[hh * 64 + fj[5:0]];
            fj <= fj + 1;
          end else begin fj <= 0; ocnt <= 0; ph <= 1'b0; st <= S_ATT; end
        end
        S_GLU: begin
          rq_scale <= c_ms; rq_shift <= c_mh;
          if (fj < 3072) begin
            si_x <= (c_gsh >= 0) ? (gm[fj] <<< c_gsh) : (gm[fj] >>> (-c_gsh));
            si_v <= 1'b1; fj <= fj + 1;
          end
          if (ocnt == 3072) begin fj <= 0; ocnt <= 0; gcnt <= 0; ph <= 1'b0; st <= S_DN; end
        end
        default: begin
          if (!ph) begin
            ph <= 1'b1; ocnt <= 0;
            if (run_proj) pj_start <= 1'b1;
            else if (in_norm) rn_start <= 1'b1;
            else if (in_hnorm) hn_start <= 1'b1;
            else at_start <= 1'b1;
            if (st == S_HD) hbase <= hk * 3072;
          end else if (!blk_busy && ocnt == expect_n && !pj_start && !rn_start && !at_start && !hn_start) begin
            ph <= 1'b0; ocnt <= 0; fj <= 0;
            case (st)
              S_N1: st <= S_Q;
              S_Q: st <= S_K;
              S_K: st <= S_V;
              S_V: st <= S_QN;
              S_QN: if (hh + 1 < 16) hh <= hh + 1;
                    else begin hh <= 0; st <= S_KN; end
              S_KN: if (hh + 1 < 8) hh <= hh + 1;
                    else begin hh <= 0; st <= S_RQ; end
              S_ATT: if (hh + 1 < 16) begin hh <= hh + 1; st <= S_LQ; end
                     else begin hh <= 0; st <= S_O; end
              S_O: st <= S_R1;
              S_N2: st <= S_G;
              S_G: st <= S_U;
              S_U: st <= S_GLU;
              S_DN: st <= S_R2;
              S_NF: st <= S_HD;
              S_HD: if (hk < 49) hk <= hk + 1;
                    else begin busy <= 1'b0; done <= 1'b1; st <= S_IDLE; end
              default: st <= S_IDLE;
            endcase
          end
        end
      endcase
    end
  end
endmodule
